var ITEMS=[["Cutty Sark: overview","Cutty Sark: Fastest clipper; tea trade icon; now Greenwich museum.."], ["name","Cutty Sark"], ["origin","Fastest clipper; tea trade icon; now Greenwich museum."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
